/**
 * Official lockup artwork (outlined vector, generated by scripts/brand/brandgen.py) —
 * never rebuilt from live text, so the logo is identical everywhere. See /brand for usage rules.
 */
export function Logo({ tone = "dark", size = "md" }: { tone?: "dark" | "light"; size?: "md" | "lg" }) {
  const src = tone === "light" ? "/brand/antrahq-logo-tagline-dark.svg" : "/brand/antrahq-logo-tagline-light.svg";
  const h = size === "lg" ? 48 : 44;
  return (
    // eslint-disable-next-line @next/next/no-img-element
    <img src={src} alt="AntraHQ — Salons & Beyond" height={h} width={Math.round(h * 3.42)} className="block w-auto" style={{ height: h }} />
  );
}
